      SUBROUTINE CORRELCC     CALCULATES PARTIALS FOR A CONSTRAINT ON THE BEAM ELLIPSE CORRELATIONCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM1D.CIN'      INCLUDE 'ELM10A.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM10D.CIN'      INCLUDE 'RC2.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'SI.CIN'      INCLUDE 'SVP.CIN'CC     LOCAL VARIABLESC      LOGICAL  LOGICCC---------------------------------------------------------------      IF (.NOT. RECENT) CALL BEAM      J = JCON      K = KCON      J = J - 10      SIJJ = SIT(J,J)      SIKK = SIT(K,K)      SIJK = SIT(J,K)      W = SIJK/SQRT(SIJJ*SIKK)      COC = W      IF (NV3 .LT. 1) GO TO 100      CW = 1.0/SD**2      A(1) = DE0 - W      CALL CLI(LOGIC)      IF (LOGIC) GO TO 150C      IF (NV1 .LT. 1) GO TO 100      DO 90 N = 1, NV1      IF (R2P) GO TO 10      IF (.NOT. SVP(N)) GO TO 90      SVJJ = SV(J,J,N)      SVKK = SV(K,K,N)      SVJK = SV(J,K,N)      GO TO 50C   10 SVJJ = 0.0      SVKK = 0.0      SVJK = 0.0      IF (SVP(N)) THEN        DO 20 L1 = 1, 6        DO 20 L2 = 1, 6        SVJJ = SVJJ + RC2(J,L1)*SV(L1,L2,N)*RC2(J,L2)        SVKK = SVKK + RC2(K,L1)*SV(L1,L2,N)*RC2(K,L2)        SVJK = SVJK + RC2(J,L1)*SV(L1,L2,N)*RC2(K,L2)   20   CONTINUE      ENDIF      IF (R2VP(N)) THEN        DO 30 L1 = 1, 6        DO 30 L2 = 1, 6        SVJJ = SVJJ + 2.0*R2V(J,L1,N)*SI(L1,L2)*RC2(J,L2)        SVKK = SVKK + 2.0*R2V(K,L1,N)*SI(L1,L2)*RC2(K,L2)        SVJK = SVJK + R2V(J,L1,N)*SI(L1,L2)*RC2(K,L2)     1       + RC2(J,L1)*SI(L1,L2)*R2V(K,L2,N)   30   CONTINUE      ENDIF   50 ANC = SVJK/SIJK - 0.5*(SVJJ/SIJJ + SVKK/SIKK)      A(N+1) = W*ANC   90 CONTINUE  100 CALL GATHERC  150 RETURN      END